"""Golden summary of the study-mode cases (see tests/test_education_golden.py).

A case id is a recipe the server replays with a deterministic sampler, so a change in the generator
(owned by the course line) or in the rules would silently change old cases. The golden file pins the
first cases of each group and level for seed 0 as hashes; it fails when either side changes.

Regenerate only when the change is intentional (agreed with the course line):

    python tests/fixtures/make_education_golden.py
    git diff tests/fixtures/education_golden.json
"""
from __future__ import annotations

import hashlib
import json

from para_triage.education import cases, scope
from para_triage.provenance_info import rules_version

SEED = 0
CASES_PER_LEVEL = 5


def case_digest(case: cases.Case) -> str:
    trace = cases.trace_of(case)
    payload = {
        "case_id": case.case_id,
        "summary": case.presentation.summary,
        "facts": [[f.label, f.value] for f in case.presentation.facts],
        "answer": case.answer,
        "masked": case.candidate.masked,
        "steps": [[s.criterion, s.reference, s.value, s.result, s.explanation] for s in trace.steps],
        "conclusion": trace.conclusion,
    }
    return hashlib.sha256(json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:16]


def build() -> dict:
    digests = {}
    for group in scope.ALLOWED_GROUPS:
        for level in scope.DIFFICULTIES:
            digests[f"{group}.{level}"] = [
                case_digest(cases.get_case(group, level, SEED, index)) for index in range(CASES_PER_LEVEL)
            ]
    return {
        "note": "Generated by tests/fixtures/make_education_golden.py. Hashes of the first cases per group and level.",
        "case_version": scope.CASE_VERSION,
        "seed": SEED,
        "rules_id": rules_version().id,
        "cases": digests,
    }
